function BAND_WIDTH_BITS(R, n, delta):
    require delta > 0
    return max(0, ceil(log2(R / (n * delta))))

function LOCATE_BAND(A, R, n, delta):
    b_star <- MIN_SAFE_BITS(A, R, n)
    m      <- BAND_WIDTH_BITS(R, n, delta)
    b_free <- b_star + m
    fatal      <- [0 .. b_star - 1]        # ranking provably inverted
    unresolved <- [b_star .. b_free - 1]   # no certificate applies
    grid       <- {b_star - 1} union [b_star .. b_free]
    return (b_star, m, b_free, fatal, unresolved, grid)

algorithms.code:
"""Band locator: the bit widths that neither certificate resolves, and the grid to run."""

from __future__ import annotations

import math
from typing import Dict, List


def min_safe_bits(A: float, R: float, n: int) -> int:
    """Least b with 2*A*n < R*2**b."""
    b = 0
    while not (2.0 * (A / 2.0 ** b) < R / n):
        b += 1
        if b > 1024:
            raise ValueError("no safe width")
    return b


def band_width_bits(R: float, n: int, delta: float) -> int:
    """ceil(log2(R / (n * delta))) -- the exact number of widths between the
    'provably inverted' certificate and the 'provably free' certificate."""
    if delta <= 0:
        raise ValueError("tolerance must be positive")
    return max(0, math.ceil(math.log2(R / (n * delta))))


def locate_band(A: float, R: float, n: int, delta: float) -> Dict[str, object]:
    """Return the fatal / unresolved / free partition of the bit axis."""
    b_star = min_safe_bits(A, R, n)
    m = band_width_bits(R, n, delta)
    b_free = b_star + m
    return {
        "context": n,
        "forced_gap": R / n,
        "min_safe_bits": b_star,
        "band_width_bits": m,
        "free_certified_from": b_free,
        "fatal_widths": list(range(0, b_star)),
        "unresolved_widths": list(range(b_star, b_free)),
        "recommended_grid": sorted({max(0, b_star - 1), *range(b_star, b_free + 1)}),
    }


def certified_ppl_multiplier(A: float, b: int) -> float:
    """exp(2 * A / 2^b): the worst-case perplexity factor the certificate allows."""
    return math.exp(2.0 * A / 2.0 ** b)


if __name__ == "__main__":
    for n in (2048, 8192, 32768):
        info = locate_band(A=1.0, R=32.0, n=n, delta=1e-3)
        print(f'context {n:>6}:  b* = {info["min_safe_bits"]:>2}   '
              f'band = {info["band_width_bits"]} bits   '
              f'unresolved = {info["unresolved_widths"]}   '
              f'grid to run = {info["recommended_grid"]}')
